[
  {
    "hypothesis_id": 2,
    "feature": {
      "name": "any_comment_cites_functioning_institutional_precedent",
      "dtype": "binary",
      "source_columns": [
        "OC_comments"
      ],
      "definition": "Counter-argument comments (OC_comments): any comment cites a specific, functioning institutional precedent (a concrete existing institution, policy, law or system that operates/has operated in practice) in support of its argument.",
      "kind": "prompt",
      "spec": "Read OC_comments (JSON list of comments by users other than the OP). Return 1 if at least one comment cites a specific institutional precedent (e.g., a particular existing law, policy, court, organization or system in a named or clearly identifiable jurisdiction/institution) presented as actually functioning or having functioned in practice, used to support the comment's argument. Examples are nonexhaustive; no external verification needed. Return 0 if no comment does so (generic or hypothetical institutions, purely abstract principles, or non-functioning/proposed-only institutions do not count). Empty list gives 0; missing or malformed OC_comments gives null. Do not use other columns."
    }
  },
  {
    "hypothesis_id": 71,
    "feature": {
      "name": "any_comment_concrete_verifiable_example",
      "dtype": "binary",
      "source_columns": [
        "OC_comments"
      ],
      "definition": "Counter-argument comments (OC_comments): any comment offers a concrete, locally verifiable example (specific instance with checkable particulars) in support of its counter-argument",
      "kind": "prompt",
      "spec": "Read the OC_comments JSON list (comments by users other than the OP). Return 1 if at least one comment, in its own voice, offers a concrete example of a specific, particular case (e.g., a specific named or otherwise identifiable person, event, place, policy, case, or personal/local situation with concrete details) whose particulars could be checked or observed directly, used to support its counter-argument. Purely abstract principles, generalities, hypotheticals without specific particulars, and vague appeals ('many people', 'in history') do not count. 'Locally verifiable' is not defined further; do not require external verification, just checkable specificity. Quoted OP text does not count. Return 0 if the list is valid and no comment qualifies (including an empty list). Return null if OC_comments is missing or malformed. Do not use other columns."
    }
  }
]

